import{_ as e,o,c as n,a2 as s}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"连接器（Connect-It）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/self-hosted/connectors.md","filePath":"zh/self-hosted/connectors.md","lastUpdated":1792323081000}'),a={name:"zh/self-hosted/connectors.md"};function r(i,t,h,d,l,p){return o(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="连接器-connect-it" tabindex="-1">连接器（Connect-It） <a class="header-anchor" href="#连接器-connect-it" aria-label="Permalink to &quot;连接器（Connect-It）&quot;">​</a></h1><p>连接器让 Bot 能用上第三方服务（GitHub、Notion 这类）的工具。背后接的是 <a href="https://github.com/memohai/connect-it" target="_blank" rel="noreferrer">Connect-It</a>，一个和 Memoh 一起部署的配套服务。所有凭据（OAuth token、API Key）都存在 Connect-It 那边；Memoh 只存一张绑定表——哪个 Bot 绑了哪个连接、工具命名空间叫什么、开没开。</p><p>对使用者来说，连接器不是单独安装的东西：它作为<a href="./../guides/supermarket.html">应用</a>的组件随 App 一起到达。App 的清单里声明了它用到哪些连接器类型、是否必需；装好后在 Bot 的 <strong>应用</strong> 标签页里完成授权即可。本页其余部分是部署方视角——怎么把 Connect-It 跑起来，以及连接背后的机制。</p><hr><h2 id="服务端前提" tabindex="-1">服务端前提 <a class="header-anchor" href="#服务端前提" aria-label="Permalink to &quot;服务端前提&quot;">​</a></h2><p>服务端配置了 Connect-It 地址，连接器功能才会出现：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">connect_it</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 例如 &quot;http://connect-it:8421&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 服务端之间的可信 token</span></span></code></pre></div><p>两项留空即关闭该功能。线上环境建议用对应的环境变量（<code>MEMOH_CONNECT_IT_BASE_URL</code>、<code>MEMOH_CONNECT_IT_API_TOKEN</code>）。</p><p>一键 Server Deploy 会在全新安装时自动带起一个同机部署的 Connect-It，见 <a href="./docker.html#connect-it-连接器">Server Deploy</a>。没配置 Connect-It 时，依赖连接器的 App 组件会显示&quot;连接器不可用&quot;。</p><hr><h2 id="授权与管理" tabindex="-1">授权与管理 <a class="header-anchor" href="#授权与管理" aria-label="Permalink to &quot;授权与管理&quot;">​</a></h2><p>装好带连接器的 App 后，Bot 的 <strong>应用</strong> 标签页会按组件列出它的连接器，并标注状态：<strong>需要授权</strong>、<strong>可选</strong>，或 <strong>所有工作区共享</strong>。点 <strong>去授权</strong> 完成绑定——OAuth 走弹窗授权（浏览器拦了弹窗就放行后重试），API Key 则填好凭据字段。</p><p>每条连接会显示状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><strong>已连接</strong></td><td>正常，工具对 Bot 可用</td></tr><tr><td><strong>等待授权</strong></td><td>连接建了但 OAuth 没走完；补完授权，或者断开它</td></tr><tr><td><strong>需要重新授权</strong></td><td>凭据过期或被撤销，点 <strong>重新授权</strong></td></tr><tr><td><strong>授权失败</strong></td><td>上次授权没成功，可再点 <strong>重新授权</strong> 重试</td></tr><tr><td><strong>不可用</strong></td><td>这个连接器类型在当前 Connect-It 侧没有提供</td></tr><tr><td><strong>已停用</strong></td><td>已停用，工具不会给到 Bot</td></tr></tbody></table><p>可以<strong>启用 / 停用</strong>某条连接而不删掉它；<strong>断开连接</strong>则把绑定从 Bot 上移除，<strong>并且</strong>删掉 Connect-It 里存的这条连接（含凭据）——之后使用它的 App 需要重新授权。</p><hr><h2 id="工具怎么到-bot-手上" tabindex="-1">工具怎么到 Bot 手上 <a class="header-anchor" href="#工具怎么到-bot-手上" aria-label="Permalink to &quot;工具怎么到 Bot 手上&quot;">​</a></h2><p>对话时，Memoh 会把这个 Bot 所有启用且状态正常的连接聚合成一个 MCP 会话，作为工具源给智能体。连接器工具和 workspace、MCP 工具并排出现。</p><p>每条连接在绑定那一刻会拿到一个按连接器类型生成的<strong>工具命名空间</strong>——GitHub 连接是 <code>github</code>，再连一个就是 <code>github-2</code>。命名空间在绑定的整个生命周期内固定不变：之后增删其它连接，不会影响已有连接的工具名。</p><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./../guides/supermarket.html">应用市场</a> —— 应用（含连接器组件）的安装入口。</li><li><a href="./../guides/mcp.html">MCP</a> —— 直接管理 MCP 连接。</li><li><a href="./docker.html#connect-it-连接器">Server Deploy</a> —— 同机部署 Connect-It、凭据管理和 OAuth 回调地址。</li></ul>`,22)])])}const k=e(a,[["render",r]]);export{g as __pageData,k as default};
